#include "compgeom/ConvexShapes.h"

// nGZCompGeom's convex bound shapes, cConvexT (lane PM, src/compgeom/ConvexShapes.h). Standalone shape: the director's
// factory hands out our shape classes, so the vtables' generic slots (QueryInterface, AddRef, Release, Clone, GetClassID,
// the linear dispatchers 24/28/32/36, ShapeData, the destructor) are in effect through callers (trap: the Create hooks).
// The shape-specific slots are hooked too, because the lights embed game-vtable shapes (src/sg/SGLightShapes.h) that no
// factory creates. Slots whose body is folded across unrelated classes (AddRef, the linear dispatchers, ShapeData, the
// "no cone" false returns shared by hundreds of classes) are not hooked.
